<template><AccountLayout bare><main class="po-page ccn-page" :aria-busy="busy">
<header class="po-header"><div class="po-heading"><FileBadge/><div><h1>Customer Credit Notes</h1><p>Accounting / Sales</p></div></div><div v-if="view==='list'" class="po-header-search"><Search/><input v-model="filters.search" placeholder="Search credit note, invoice, PO or customer..."></div><div class="po-actions"><button v-if="view==='list'" class="po-btn primary" @click="startNew"><Plus/> New Customer Credit Note</button><button v-else class="po-btn" @click="back"><ArrowLeft/> Back to list</button></div></header>
<div v-if="error" class="po-alert error">{{ error }}</div><div v-if="notice" class="po-alert success">{{ notice }}</div>
<template v-if="view==='list'"><section class="po-metrics"><article v-for="card in metrics" :key="card.label" :class="card.tone"><component :is="card.icon"/><div><h2>{{ card.label }}</h2><strong>{{ card.count }} Credit Notes</strong><b>{{ negative(card.amount) }} USD</b></div></article></section><form class="po-filters" @submit.prevent="page=1"><label>Date Range<span class="po-date-range"><input v-model="filters.from" type="date"><input v-model="filters.to" type="date"></span></label><label>Customer<select v-model="filters.customer"><option value="">All Customers</option><option v-for="x in customers" :key="x">{{ x }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All Status</option><option v-for="x in statuses" :key="x">{{ x }}</option></select></label><label>Department<select v-model="filters.department"><option value="">All Departments</option><option v-for="x in departments" :key="x">{{ x }}</option></select></label><button class="po-btn primary"><Search/> Search</button><button class="po-btn" type="button" @click="filters=initialFilters()"><RotateCcw/> Reset</button></form><section class="po-list"><header class="po-section-head"><h2>Customer Credit Note List</h2><div class="po-actions"><button class="po-btn primary" @click="startNew"><Plus/> New Customer Credit Note</button><button class="po-btn green" @click="exportExcel"><Download/> Export</button></div></header><div class="po-table-scroll"><table class="po-list-table"><thead><tr><th>No.</th><th>Credit Note No.</th><th>Credit Note Date</th><th>Invoice No.</th><th>Invoice Date</th><th>PO No.</th><th>Customer No.</th><th>Customer Name</th><th>Credit Amount</th><th>Reason</th><th>Status</th><th>View</th></tr></thead><tbody><tr v-for="(row,index) in paginated" :key="row.id"><td>{{ (page-1)*perPage+index+1 }}</td><td><button class="po-link" @click="openNote(row)">{{ row.credit_note_no }}</button></td><td>{{ dateLabel(row.credit_note_date) }}</td><td>{{ source(row).invoice_no }}</td><td>{{ dateLabel(source(row).invoice_date) }}</td><td>{{ source(row).customer_po_no||'-' }}</td><td>{{ customer(row).customer_no||'-' }}</td><td>{{ customer(row).name||'-' }}</td><td class="po-negative">{{ negative(row.total) }}</td><td>{{ row.reason }}</td><td><span class="po-pill" :class="slug(row.status)">{{ row.status }}</span></td><td><button class="po-btn compact" @click="openNote(row)"><Eye/> View</button></td></tr><tr v-if="!paginated.length"><td colspan="12" class="po-empty">No customer credit notes found.</td></tr></tbody></table></div><footer class="po-pagination"><span>Showing {{ filtered.length?(page-1)*perPage+1:0 }} to {{ Math.min(page*perPage,filtered.length) }} of {{ filtered.length }}</span><div class="po-actions"><button class="po-icon" :disabled="page===1" @click="page--"><ChevronLeft/></button><b>{{ page }} / {{ pages }}</b><button class="po-icon" :disabled="page===pages" @click="page++"><ChevronRight/></button></div></footer></section></template>
<div v-else class="po-workspace"><section class="po-document"><header class="po-document-head"><div class="po-heading"><FileBadge/><h2>Customer Credit Note</h2></div><div class="po-actions"><b>{{ form.credit_note_no||'New credit note' }}</b><span class="po-pill" :class="slug(form.status)">{{ form.status }}</span><button class="po-icon" title="Print" @click="printPage"><Printer/></button><button class="po-icon" title="Email" @click="emailNote"><Mail/></button></div></header><div class="po-document-body"><div class="po-details-grid"><section><h3>Customer</h3><Field label="Account No." :model-value="customer().customer_no"/><Field label="Customer Name" :model-value="customer().name"/><Field label="Company" :model-value="customer().name"/><Field label="Phone" :model-value="customer().phone"/><Field label="Email" :model-value="customer().email"/><Field label="Website" :model-value="customer().website"/><Field label="Address" :model-value="customer().address" multiline/><Field label="Contact Person" :model-value="customer().contact_person"/></section><section><h3>Credit Note Details</h3><div v-if="editing" class="po-field"><label>Sales Invoice No.</label><i>:</i><select v-model="form.sales_invoice_id" @change="applyInvoice"><option :value="null" disabled>Select invoice</option><option v-for="x in eligibleInvoices" :key="x.id" :value="x.id">{{ x.invoice_no }} - {{ x.customer_details?.name }}</option></select></div><Field v-else label="Sales Invoice No." :model-value="invoice.invoice_no"/><Field label="Credit Note No." v-model="form.credit_note_no" :editable="editing"/><Field label="Credit Note Date" v-model="form.credit_note_date" :editable="editing" type="date" :display-value="dateLabel(form.credit_note_date)"/><Field label="Sales Invoice Date" :model-value="dateLabel(invoice.invoice_date)"/><Field label="Sales Order No." :model-value="invoice.sales_order?.order_no"/><Field label="Customer PO No." :model-value="invoice.customer_po_no"/><Field label="Payment Terms" :model-value="invoice.payment_terms"/><Field label="Currency" :model-value="invoice.currency_code"/><Field label="Status" :model-value="form.status"/><Field label="Type" model-value="Customer Credit Note"/><Field label="Reason" v-model="form.reason" :editable="editing" :options="reasons"/></section><section><h3>Info</h3><Field label="Credit Note Status" :model-value="form.status"/><Field label="Project Name" :model-value="invoice.job_site_name"/><Field label="Project Site Address" :model-value="invoice.job_site_address" multiline/><Field label="Tax Registration No." :model-value="invoice.tax_registration_no"/><Field label="Internal Notes" v-model="form.notes" :editable="editing" multiline/><Field label="Prepared By" :model-value="form.creator?.name"/><Field label="Approved By" :model-value="invoice.approved_by"/><Field label="Last Update" :model-value="dateTimeLabel(form.updated_at)"/></section></div>
<section class="po-items"><div v-if="editing" class="po-section-head"><h3>Details</h3><button class="po-btn compact primary" @click="addItem"><Plus/> Add line</button></div><div class="po-table-scroll"><table><thead><tr><th>No.</th><th>Item / Service</th><th>Description</th><th>UOM</th><th>Qty</th><th>Unit Price</th><th>Discount (%)</th><th>Tax (%)</th><th>Total</th><th v-if="editing"></th></tr></thead><tbody><tr v-for="(item,index) in form.items" :key="index"><td>{{ index+1 }}</td><td><input v-if="editing" v-model="item.name"><span v-else>{{ item.name }}</span></td><td><input v-if="editing" v-model="item.description"><span v-else>{{ item.description||'-' }}</span></td><td><input v-if="editing" v-model="item.uom"><span v-else>{{ item.uom }}</span></td><td><input v-if="editing" v-model.number="item.quantity" type="number" min=".01" step=".01"><span v-else>{{ money(item.quantity) }}</span></td><td><input v-if="editing" v-model.number="item.unit_price" type="number" min="0" step=".01"><span v-else class="po-negative">{{ negative(item.unit_price) }}</span></td><td><input v-if="editing" v-model.number="item.discount" type="number" min="0" max="100"><span v-else>{{ money(item.discount) }}</span></td><td><input v-if="editing" v-model.number="item.tax_rate" type="number" min="0" max="100"><span v-else>{{ money(item.tax_rate) }}</span></td><td class="po-negative">{{ negative(itemTotal(item)) }}</td><td v-if="editing"><button class="po-icon danger" @click="form.items.splice(index,1)"><Trash2/></button></td></tr><tr v-if="!form.items.length"><td :colspan="editing?10:9" class="po-empty">No credit lines added.</td></tr></tbody><tfoot><tr><th colspan="5">Amount in Words</th><th colspan="3">Total</th><th class="po-negative">{{ negative(total) }}</th><th v-if="editing"></th></tr></tfoot></table></div><div class="ccn-amount-words">{{ amountInWords }}</div></section>
<div class="po-bottom-grid"><section><h3>Terms &amp; Conditions</h3><textarea v-if="editing" v-model="form.terms" rows="6"/><p v-else class="po-terms">{{ form.terms||'-' }}</p></section><section><h3>Notes</h3><textarea v-if="editing" v-model="form.notes" rows="6"/><p v-else class="po-terms">{{ form.notes||'-' }}</p></section><section class="po-totals"><Field label="Subtotal" :model-value="negative(subtotal)"/><Field label="Discount" :model-value="negative(discount)"/><Field label="Sales Tax" :model-value="negative(tax)"/><div><span>Total ({{ invoice.currency_code||'USD' }})</span><strong class="po-negative">{{ negative(total) }}</strong></div></section></div><section v-if="form.attachments.length" class="po-attachments"><h3>Attachments</h3><button v-for="file in form.attachments" :key="file.id" class="po-btn compact" @click="downloadAttachment(file)"><Paperclip/> {{ file.name }}</button></section></div>
<footer class="po-document-footer"><div class="po-actions"><button class="po-btn" @click="startNew"><Plus/> New</button><button class="po-btn" :disabled="editing||form.status==='Approved'" @click="editing=true"><Pencil/> Edit</button><button class="po-btn danger" :disabled="!form.id||form.status==='Approved'" @click="deleteNote"><Trash2/> Delete</button><button class="po-btn primary" :disabled="!editing" @click="saveNote"><Save/> Save</button><button v-if="editing" class="po-btn" @click="cancel"><X/> Cancel</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn" @click="printPage"><Eye/> Preview</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="emailNote"><Mail/> Email</button><button class="po-btn" :disabled="!form.id" @click="fileInput.click()"><Paperclip/> Attach File</button><input ref="fileInput" class="po-hidden" type="file" @change="upload"><button class="po-btn" :disabled="!form.id" @click="modal='audit'"><History/> Audit Log</button><button class="po-btn amber" :disabled="!canSubmit" @click="workflow('submit')"><Send/> Send for Approval</button><button class="po-btn green" :disabled="!canDecide" @click="workflow('approve')"><Check/> Approve</button><button class="po-btn danger" :disabled="!canDecide" @click="workflow('reject')"><X/> Reject</button></div></footer></section>
<aside class="po-sidebar"><section><h3>Sales Tracker</h3><div class="po-table-scroll"><table class="po-tracker"><thead><tr><th>Doc Type</th><th>Doc No.</th><th>Subtotal</th><th>Sales Tax</th><th>Total</th></tr></thead><tbody><tr><td>Sales Estimation</td><td>{{ invoice.sales_order?.estimation?.estimation_no||'-' }}</td><td>{{ money(invoice.subtotal) }}</td><td>{{ money(invoice.sales_tax) }}</td><td>{{ money(invoice.total) }}</td></tr><tr><td>Sales Order</td><td>{{ invoice.sales_order?.order_no||'-' }}</td><td>{{ money(invoice.subtotal) }}</td><td>{{ money(invoice.sales_tax) }}</td><td>{{ money(invoice.total) }}</td></tr><tr><td>Sales Invoice</td><td>{{ invoice.invoice_no||'-' }}</td><td>{{ money(invoice.subtotal) }}</td><td>{{ money(invoice.sales_tax) }}</td><td>{{ money(invoice.total) }}</td></tr><tr><td>Sales Return</td><td>{{ approvedReturns.length }}</td><td colspan="2"></td><td class="po-negative">{{ negative(returnTotal) }}</td></tr><tr><td>Customer Credit Note</td><td>{{ form.credit_note_no||'-' }}</td><td class="po-negative">{{ negative(subtotal-discount) }}</td><td class="po-negative">{{ negative(tax) }}</td><td class="po-negative">{{ negative(total) }}</td></tr></tbody><tfoot><tr><th>Current Balance</th><th colspan="3">{{ invoice.currency_code }}</th><th>{{ money(currentBalance) }}</th></tr></tfoot></table></div></section><section><h3>Quick Report</h3><button v-for="x in reports" :key="x" class="po-report-link"><span>{{ x }}</span><ChevronRight/></button></section><section><h3>Quick Action</h3><button class="po-report-link"><span>Convert to Customer Payment</span><ChevronRight/></button><button class="po-report-link"><span>Convert to Debit Note</span><ChevronRight/></button></section></aside></div>
<div v-if="modal" class="po-modal-backdrop" @click.self="modal=''"> <section class="po-modal"><header><h2>Customer Credit Note Audit Log</h2><button class="po-icon" @click="modal=''"><X/></button></header><div class="po-table-scroll"><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><tr v-for="x in form.activities" :key="x.id"><td>{{ dateTimeLabel(x.created_at) }}</td><td>{{ x.actor }}</td><td>{{ x.action }}</td><td>{{ details(x.changes) }}</td></tr></tbody></table></div></section></div>
</main></AccountLayout></template>
<script setup>
import{computed,onMounted,ref,watch}from'vue';import{FileBadge,Search,Plus,ArrowLeft,RotateCcw,Download,Eye,Printer,Mail,ChevronLeft,ChevronRight,FileDown,Trash2,Pencil,Save,X,Check,Paperclip,History,Send,WalletCards,BadgeCheck,Clock,XCircle}from'lucide-vue-next';import AccountLayout from'../components/AccountLayout.vue';import Field from'../components/PurchaseOrderField.vue';import client from'../api/client';import{roundMoney,today,money,dateLabel,dateTimeLabel}from'../utils/purchaseOrders'
const rows=ref([]),invoices=ref([]),view=ref('list'),form=ref({}),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),fileInput=ref(null),page=ref(1),perPage=ref(15),statuses=['Draft','Pending','Approved','Rejected'],reasons=['Price Adjustment','Additional Discount','Billing Error','Service Credit','Damaged Goods','Overpayment','Other'],reports=['AR Aging Report','Customer Account Statement','Customer Payments List','Sales Tax','Customer Note'];const initialFilters=()=>({search:'',from:'',to:'',customer:'',status:'',department:''}),filters=ref(initialFilters()),blank=()=>({id:null,credit_note_no:'',sales_invoice_id:null,credit_note_date:today(),status:'Draft',reason:'',items:[],terms:'1. This credit note is issued for the reason mentioned above.\n2. The amount will be adjusted in the customer account.\n3. This is not a cash refund.\n4. Taxes apply according to current regulations.',notes:'This credit note will be adjusted against future invoices.',activities:[],attachments:[],sales_invoice:null})
const source=x=>x?.sales_invoice||{},invoice=computed(()=>source(form.value)),customer=x=>source(x||form.value).customer_details||{},slug=x=>String(x||'').toLowerCase().replace(/\s+/g,'-'),negative=x=>'('+money(x)+')',eligibleInvoices=computed(()=>invoices.value.filter(x=>['Open','Paid'].includes(x.status))),customers=computed(()=>[...new Set(rows.value.map(x=>customer(x).name).filter(Boolean))].sort()),departments=computed(()=>[...new Set(rows.value.map(x=>source(x).department).filter(Boolean))].sort())
const filtered=computed(()=>rows.value.filter(x=>{const f=filters.value,i=source(x),q=f.search.toLowerCase(),d=String(x.credit_note_date||'').slice(0,10);return(!q||[x.credit_note_no,i.customer_po_no,i.invoice_no,customer(x).name].some(v=>String(v||'').toLowerCase().includes(q)))&&(!f.customer||customer(x).name===f.customer)&&(!f.department||i.department===f.department)&&(!f.status||x.status===f.status)&&(!f.from||d>=f.from)&&(!f.to||d<=f.to)})),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),paginated=computed(()=>filtered.value.slice((page.value-1)*perPage.value,page.value*perPage.value))
const base=x=>Number(x.quantity||0)*Number(x.unit_price||0),itemDiscount=x=>base(x)*Number(x.discount||0)/100,itemTax=x=>(base(x)-itemDiscount(x))*Number(x.tax_rate||0)/100,itemTotal=x=>roundMoney(base(x)-itemDiscount(x)+itemTax(x)),subtotal=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+base(x),0))),discount=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+itemDiscount(x),0))),tax=computed(()=>roundMoney((form.value.items||[]).reduce((s,x)=>s+itemTax(x),0))),total=computed(()=>roundMoney(subtotal.value-discount.value+tax.value)),approvedReturns=computed(()=>invoice.value.returns?.filter(x=>x.status==='Returned')||[]),returnTotal=computed(()=>approvedReturns.value.reduce((s,x)=>s+Number(x.total),0)),currentBalance=computed(()=>Math.max(0,Number(invoice.value.total||0)-returnTotal.value-total.value)),amountInWords=computed(()=>money(total.value)+' '+(invoice.value.currency_code||'USD')+' only')
const canSubmit=computed(()=>form.value.id&&!editing.value&&['Draft','Rejected'].includes(form.value.status)),canDecide=computed(()=>form.value.id&&!editing.value&&['Draft','Pending'].includes(form.value.status)),metrics=computed(()=>statuses.map((status,index)=>{const set=filtered.value.filter(x=>status==='Draft'?true:x.status===status);return{label:index===0?'Total Credit Notes':'Total '+status,count:set.length,amount:set.reduce((s,x)=>s+Number(x.total),0),icon:[WalletCards,BadgeCheck,Clock,XCircle][index],tone:['blue','green','amber','red'][index]}})),apiError=e=>Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message
async function all(url){let p=1,last=1,out=[];do{const{data}=await client.get(url,{params:{per_page:100,page:p}}),b=data.data;out.push(...(b?.data||b||[]));last=b?.last_page||1;p++}while(p<=last);return out}async function load(){[rows.value,invoices.value]=await Promise.all([all('/customer-credit-notes'),all('/sales-invoices')])}function normalize(x){return{...blank(),...x,sales_invoice_id:x.sales_invoice_id?Number(x.sales_invoice_id):null,credit_note_date:String(x.credit_note_date||today()).slice(0,10),items:(x.items||[]).map(i=>({...i})),activities:x.activities||[],attachments:x.attachments||[]}}function startNew(){form.value=blank();editing.value=true;view.value='detail';error.value=''}async function openNote(x){busy.value=true;try{const{data}=await client.get('/customer-credit-notes/'+x.id);form.value=normalize(data.data);editing.value=false;view.value='detail'}catch(e){error.value=apiError(e)}finally{busy.value=false}}function back(){view.value='list';editing.value=false}async function cancel(){form.value.id?await openNote(form.value):back()}function applyInvoice(){const x=invoices.value.find(i=>i.id===Number(form.value.sales_invoice_id));if(x){form.value.sales_invoice=x}}function addItem(){const x=invoice.value.items?.[0]||{};form.value.items.push({name:'Additional Discount',description:'Credit adjustment',uom:'LS',quantity:1,unit_price:0,discount:0,tax_rate:Number(x.tax_rate||0)})}
async function saveNote(){if(!form.value.sales_invoice_id||!form.value.reason||!form.value.items.length){error.value='Select an invoice, reason, and add a credit line.';return}try{const{data}=form.value.id?await client.put('/customer-credit-notes/'+form.value.id,form.value):await client.post('/customer-credit-notes',form.value);form.value=normalize(data.data);editing.value=false;await load();notice.value='Customer credit note saved.'}catch(e){error.value=apiError(e)}}async function workflow(action){try{const{data}=await client.post('/customer-credit-notes/'+form.value.id+'/workflow',{action});form.value=normalize(data.data);await load();notice.value='Credit note '+form.value.status.toLowerCase()+'.'}catch(e){error.value=apiError(e)}}async function deleteNote(){if(!confirm('Delete '+form.value.credit_note_no+'?'))return;try{await client.delete('/customer-credit-notes/'+form.value.id);await load();back()}catch(e){error.value=apiError(e)}}
async function upload(e){const f=e.target.files[0];if(!f)return;const b=new FormData();b.append('file',f);try{const{data}=await client.post('/customer-credit-notes/'+form.value.id+'/attachments',b);form.value=normalize(data.data)}catch(x){error.value=apiError(x)}finally{e.target.value=''}}async function downloadAttachment(f){const{data}=await client.get('/customer-credit-notes/'+form.value.id+'/attachments/'+f.id,{responseType:'blob'});downloadBlob(data,f.name)}function downloadBlob(b,n){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function details(v){try{return Object.entries(typeof v==='string'?JSON.parse(v):v||{}).map(([k,x])=>k+': '+x).join(', ')}catch{return''}}
function printPage(){window.print()}function emailNote(){window.location.href='mailto:'+encodeURIComponent(customer().email||'')+'?subject='+encodeURIComponent('Customer Credit Note '+(form.value.credit_note_no||''))}async function savePdf(){const{default:jsPDF}=await import('jspdf'),p=new jsPDF();p.setFontSize(18);p.text('Customer Credit Note '+(form.value.credit_note_no||''),15,18);p.setFontSize(10);p.text('Customer: '+(customer().name||'-'),15,30);p.text('Invoice: '+(invoice.value.invoice_no||'-'),15,37);let y=50;(form.value.items||[]).forEach(x=>{p.text([x.name,x.quantity+' '+x.uom,negative(itemTotal(x))].join(' | '),15,y);y+=7});p.text('Total: '+negative(total.value),15,y+7);p.save((form.value.credit_note_no||'customer-credit-note')+'.pdf')}async function exportExcel(){const{default:ExcelJS}=await import('exceljs'),b=new ExcelJS.Workbook(),s=b.addWorksheet('Customer Credit Notes');s.addRow(['Credit Note','Invoice','Customer','Date','Amount','Reason','Status']);filtered.value.forEach(x=>s.addRow([x.credit_note_no,source(x).invoice_no,customer(x).name,dateLabel(x.credit_note_date),-Number(x.total),x.reason,x.status]));s.columns.forEach(x=>x.width=22);downloadBlob(new Blob([await b.xlsx.writeBuffer()]),'customer-credit-notes.xlsx')}watch([filters,perPage],()=>page.value=1,{deep:true});onMounted(async()=>{busy.value=true;try{await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script><style src="../assets/purchase-orders.css"></style><style>.ccn-page .ccn-amount-words{border:1px solid #dce3ef;border-top:0;padding:12px;font-weight:600}.ccn-page .po-details-grid{grid-template-columns:1fr 1.08fr 1fr}.ccn-page .po-negative{color:#e00000}.ccn-page .po-totals>div>strong{font-size:14px;line-height:1.2;white-space:nowrap;overflow-wrap:normal;word-break:normal;flex:0 0 auto}@media(max-width:900px){.ccn-page .po-details-grid{grid-template-columns:1fr}}</style>
